ps.pstext:
if !IsFeatureImplemented(FEAT_MTE) then
    Undefined();
elsif PSTATE.EL == EL0 then
    if EffectivelyAtEL0NotInHost() && SCTLR_EL1().DZE == '0' then
        AArch64_SystemAccessTraptoEL1orEL2(0x18);
    elsif EL2Enabled() && EffectivelyAtEL0NotInHost() && HCR_EL2().TDZ == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && EffectivelyAtEL0NotInHost() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCZVA == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EffectivelyAtEL0InHost() && SCTLR_EL2().DZE == '0' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_MemZero(X{64}(t), CacheType_Tag);
    end;
elsif PSTATE.EL == EL1 then
    if EL2Enabled() && HCR_EL2().TDZ == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    elsif EL2Enabled() && IsFeatureImplemented(FEAT_FGT) && (!HaveEL(EL3) || SCR_EL3().FGTEn == '1') && HFGITR_EL2().DCZVA == '1' then
        AArch64_SystemAccessTrap(EL2, 0x18);
    else
        AArch64_MemZero(X{64}(t), CacheType_Tag);
    end;
elsif PSTATE.EL == EL2 then
    AArch64_MemZero(X{64}(t), CacheType_Tag);
elsif PSTATE.EL == EL3 then
    AArch64_MemZero(X{64}(t), CacheType_Tag);
end;
